/** 面板绑在它所在楼层的变量上，和挂机脚本读写的是同一份。 */
export const use变量 = defineMvuDataStore(Schema, {
  type: 'message',
  message_id: getCurrentMessageId(),
});

/** 挂机账目的开关与间隔。面板显示倒计时时也用这一份，免得两处对不上。 */
export const 结算间隔小时 = 12;
