import { onUnmounted, ref } from 'vue';

/**
 * 小游戏共用的计时与计分。
 *
 * 四款游戏都用同一套：一题一次判断，点对算对，点错算错，
 * 得分 = 答对题数 / 总题数 × 100。不比手速，手机上也能玩。
 *
 * 每款游戏只需要负责「这一题的题面与选项长什么样」，其余交给它。
 */
export function use小游戏(参数: { 题数: number; 每题秒数?: number }) {
  const 总秒 = Math.max(45, Math.min(120, Math.round(参数.题数 * (参数.每题秒数 ?? 11))));
  const 剩余 = ref(总秒);
  const 题号 = ref(1);
  const 对了几题 = ref(0);
  const 提示 = ref('');
  const 结束 = ref(false);

  const 计时器 = window.setInterval(() => {
    if (结束.value) return;
    剩余.value -= 1;
    if (剩余.value <= 0) 结算();
  }, 1000);

  onUnmounted(() => window.clearInterval(计时器));

  function 答对(说明?: string) {
    if (结束.value) return;
    对了几题.value += 1;
    提示.value = 说明 ?? '对了';
    翻页();
  }

  function 答错(说明?: string) {
    if (结束.value) return;
    提示.value = 说明 ? `错了。${说明}` : '错了';
    翻页();
  }

  function 翻页() {
    if (题号.value >= 参数.题数) {
      结算();
      return;
    }
    window.setTimeout(() => {
      题号.value += 1;
      提示.value = '';
    }, 650);
  }

  function 结算() {
    if (结束.value) return;
    结束.value = true;
    window.clearInterval(计时器);
    const 得分 = Math.round((对了几题.value / 参数.题数) * 100);
    发出得分(得分);
  }

  /** 没做完就收工：按已经答过的题算，一道没答就是 0 分。 */
  function 提前收工() {
    if (结束.value) return;
    结束.value = true;
    window.clearInterval(计时器);
    const 答过的 = Math.max(1, 题号.value - (提示.value ? 0 : 1));
    const 得分 = Math.round((对了几题.value / 答过的) * 100);
    发出得分(得分);
  }

  let 收分回调: (得分: number) => void = () => undefined;
  function 发出得分(得分: number) {
    收分回调(得分);
  }
  function 接管收分(回调: (得分: number) => void) {
    收分回调 = 回调;
  }

  return { 总秒, 剩余, 题号, 对了几题, 提示, 结束, 答对, 答错, 提前收工, 接管收分 };
}
