/* 知夏 · 挂机结算
 *
 * 这张卡的核心：妹妹自己在这里活着。玩家离开多久，她的状态就往下掉多少。
 * 这里用一个**纯函数**算这件事，输入是「上次离开的时刻」和「现在」，输出是一份差额。
 * 纯函数的好处是本地能直接拿数字跑，不必进酒馆；面板与脚本都调同一份，不会各算一套。
 *
 * 三条底线：
 * 1. 离开越久掉得越多，但有上限。上限是「最多按几天算」，超过就按上限算（`最长补偿小时`）。
 * 2. 时间倒退（玩家改了系统时钟）按零处理，不倒涨。
 * 3. 饥饿归零之后健康才开始掉，形成一条连锁，但不至于一夜之间掉光。
 */

/* ── 可调参数：想改松紧就改这里 ───────────────────── */

/** 超过这个时长（小时）就按这个时长算，不再继续掉。72 小时 = 三天。 */
export const 最长补偿小时 = 72;

/** 每过一天妹妹的饥饿掉多少。 */
export const 饥饿日损 = 55;
/** 一次挂机最多掉多少饥饿。这个数要明显高于「一天」的量，否则离开一天和离开一周看起来一样。 */
export const 饥饿上限 = 60;

/** 每过一天心情掉多少。 */
export const 心情日损 = 10;
/** 一次挂机最多掉多少心情。 */
export const 心情上限 = 60;

/** 每过一天健康掉多少（只有在她饿着或者病着的时候才掉）。 */
export const 健康日损 = 8;
/** 一次挂机最多掉多少健康。 */
export const 健康上限 = 12;

/**
 * 每过一天，依赖往下走多少。
 * 这一条是「你不陪她，她就慢慢不指望你」的机制：挂着不管，她会长成自己能扛的样子。
 * 它掉得比心情慢，上限也高，所以离开一个月和离开一周看得出来差别。
 */
export const 依赖日损 = 4;
/** 一次挂机最多掉多少依赖。 */
export const 依赖上限 = 70;

/** 一天里能陪她几次、能出工几次。这就是「分身乏术」，也只在真实时间跨过一天后刷新。 */
export const 一天能陪几次 = 1;
export const 一天能出工几次 = 1;

/** 她饿到这个数以下，健康才开始跟着掉。 */
export const 饿到这份上会伤身 = 30;

/**
 * 他每天的固定开销（房租、水电、米面钱）。
 * 钱要靠玩小游戏挣，挂机本身不产生收入，这里只扣开销。
 */
export const 日开销 = 120;
/** 一次挂机最多按几天结算开销。 */
export const 钱最长结算天数 = 7;

/** 一年按多少天算。用来把「过了几天」折算成年龄。 */
export const 一年天数 = 365;

/**
 * 开局年龄。年龄不再由玩家选，开局就是八岁，往后随挂机时间往上长。
 * 这个基准必须和 `schema.ts` 里的 `起始年龄` 一致，
 * 否则 `5 + 天数/365` 这种写法一开局就会把她算成八岁以上。
 */
export const 起始年龄 = 8;

/* ── 结算本身 ───────────────────────────────── */

export type 差额 = {
  /** 算状态时按多久（小时）。被单次上限截过之后的值。 */
  折合小时: number;
  /** 算状态时折算的天数。会封顶。 */
  折合天数: number;
  /** 真实经过的天数。日历按它走，不封顶。 */
  实际天数: number;
  饥饿: number;
  心情: number;
  健康: number;
  依赖: number;
  钱: number;
  /** 她一个人过了多久，给界面显示与正文引用。 */
  离开小时: number;
  /** 状态那一份是否被单次上限截断过。截断时界面要说清楚。 */
  被截断: boolean;
};

export type 结算输入 = {
  上次时刻: number;
  现在时刻: number;
  现在的饥饿: number;
  现在的心情: number;
  现在的健康: number;
  现在的钱: number;
  /** 她现在的病症。病着的时候这段时间更伤身。 */
  病症?: string;
};

/** 把毫秒差换成小时，负数与异常值一律按 0。 */
function 小时差(上次时刻: number, 现在时刻: number) {
  const 差 = Number(现在时刻) - Number(上次时刻);
  if (!Number.isFinite(差) || 差 <= 0) return 0;
  return 差 / 3600000;
}

/**
 * 算这一段离开造成的全部变化。
 * 返回的是**差额**（负数代表减少），调用方自己决定怎么加到变量上。
 *
 * 两份时间分开算，这是这张卡的规矩：
 *
 * - 日子不封顶：真实过了多少天，日历就走多少天。离开一周就是一周，离开一个月就是一个月。
 *   日历跟真实时间对齐，不能骗人。
 * - 状态有封顶：饥饿、心情、健康、依赖各有单次上限。它管的是「一次结算最多让她掉多少」，
 *   不管时间走多快。所以三天没回和一周没回，她掉的一样多，但日历会老实地走三天和七天。
 */
export function 算离线(输入: 结算输入): 差额 {
  const 离开小时 = 小时差(输入.上次时刻, 输入.现在时刻);

  if (离开小时 <= 0) {
    return {
      折合小时: 0,
      折合天数: 0,
      实际天数: 0,
      饥饿: 0,
      心情: 0,
      健康: 0,
      依赖: 0,
      钱: 0,
      离开小时: 0,
      被截断: false,
    };
  }

  // 真实天数：日历按它走，不封顶
  const 实际天数 = 离开小时 / 24;

  // 折算天数：状态按它算，封顶
  const 被截断 = 离开小时 > 最长补偿小时;
  const 折合小时 = Math.min(离开小时, 最长补偿小时);
  const 折合天数 = 折合小时 / 24;

  // 饥饿与心情按天数线性掉，各自封顶
  const 饥饿 = -Math.min(饥饿上限, Math.round(折合天数 * 饥饿日损));
  const 心情 = -Math.min(心情上限, Math.round(折合天数 * 心情日损));

  // 依赖：你不陪她，她就慢慢不指望你。这一条是长线，掉得比饥饿慢
  const 依赖 = -Math.min(依赖上限, Math.round(折合天数 * 依赖日损));

  // 健康：只有她本来就饿着、或者正在病着，这段时间才伤身
  let 健康 = 0;
  const 会伤身 = 输入.现在的饥饿 < 饿到这份上会伤身 || (输入.现在的病症 ?? '无') !== '无';
  if (会伤身) 健康 = -Math.min(健康上限, Math.round(折合天数 * 健康日损));

  // 钱：这几天他也在过日子，固定开销照扣。
  // 收入不在这里：钱要靠面板上的小游戏挣，挂机只是让日子继续过。
  const 钱天数 = Math.min(实际天数, 钱最长结算天数);
  const 钱 = -Math.round(钱天数 * 日开销);

  return { 折合小时, 折合天数, 实际天数, 饥饿, 心情, 健康, 依赖, 钱, 离开小时, 被截断 };
}

/** 把小时数说成人话，界面与正文都用这一句。 */
export function 说时长(小时: number) {
  if (小时 < 1) return '不到一个小时';
  if (小时 < 24) return `${Math.round(小时)} 个小时`;
  const 天 = Math.floor(小时 / 24);
  const 余 = Math.round(小时 - 天 * 24);
  return 余 > 0 ? `${天} 天 ${余} 小时` : `${天} 天`;
}

export type 收支 = {
  /** 这一趟是不是刚好跨过了生日，界面要单独提一句。 */
  年龄长了一岁: boolean;
  /** 这一趟跨过了几天（跨天就把今天的时间预算清零）。 */
  跨了几天: number;
};

/** 把差额应用到一份变量上。就地改，调用方传进来的那份。 */
export function 应用到妹妹(数据: any, 差额: 差额): 收支 {
  const 钳 = (值: number) => Math.max(0, Math.min(100, 值));
  数据.妹妹.饥饿 = 钳(Number(数据.妹妹.饥饿) + 差额.饥饿);
  数据.妹妹.心情 = 钳(Number(数据.妹妹.心情) + 差额.心情);
  数据.妹妹.健康 = 钳(Number(数据.妹妹.健康) + 差额.健康);
  数据.妹妹.依赖 = 钳(Number(数据.妹妹.依赖) + 差额.依赖);
  数据.钱 = Math.max(0, Number(数据.钱) + 差额.钱);

  // 日历按真实天数走，不封顶。这是「时间完全对照真实时间」的落点。
  const 跨了几天 = Math.floor(差额.实际天数);
  数据.时间.总天数 = Number(数据.时间.总天数 ?? 0) + 跨了几天;

  // 日历本身也按真实天数推，不靠谁去改。年/月/日 从总天数算出来，和季节一致。
  日历(数据);

  // 跨过一天就把今天的互动余量清空：新的一天，家里又能喂几回、照顾几回、出一次工。
  if (跨了几天 > 0 && 数据.今日 && typeof 数据.今日 === 'object') {
    数据.今日.陪过 = 0;
    数据.今日.喂过 = 0;
    数据.今日.药过 = 0;
    数据.今日.买过 = 0;
    数据.今日.出过工 = 0;
    数据.今日.日期 = '';
  }

  // 天数推着年龄走：每满一年长一岁，阶段跟着改
  const 原年龄 = Number(数据.妹妹.年龄);
  const 新年龄 = Math.min(16, 起始年龄 + Math.floor(Number(数据.时间.总天数 ?? 0) / 一年天数));
  let 年龄长了一岁 = false;
  if (新年龄 !== 原年龄) {
    数据.妹妹.年龄 = 新年龄;
    数据.妹妹.阶段 = 取阶段(新年龄);
    年龄长了一岁 = 新年龄 > 原年龄;
  }
  return { 年龄长了一岁, 跨了几天 };
}

/** 开局的那一天：第 1 年的 3 月 1 日，春。往后由真实时间往上推。 */
export const 开局月 = 3;
export const 开局日 = 1;

/**
 * 从总天数推年、月、日、季节。
 * 一年按 12 个月、每月 30 天算，简单但一致：日子只由天数决定，不会各处对不上。
 * 起点是 `开局月/开局日`，所以第 0 天就是 3 月 1 日，不是 1 月 1 日。
 */
export function 日历(数据: any) {
  const 天 = Math.max(0, Math.floor(Number(数据.时间?.总天数 ?? 0)));
  const 全年 = 360;
  const 年 = 1 + Math.floor(天 / 全年);
  const 年内第几天 = 天 % 全年;
  const 月的偏移 = (开局月 - 1) * 30 + (开局日 - 1);
  const 月内 = (月的偏移 + 年内第几天) % 全年;
  数据.时间.年 = 年;
  数据.时间.月 = 1 + Math.floor(月内 / 30);
  数据.时间.日 = 1 + (月内 % 30);
  数据.时间.季节 = 数据.时间.月 <= 2 || 数据.时间.月 === 12 ? '冬' : 数据.时间.月 <= 5 ? '春' : 数据.时间.月 <= 8 ? '夏' : '秋';
}

/** 今天还能陪几次、还能出几次工。面板拿它显示剩余额度，也拿它挡按钮。 */
export function 今日还能(数据: any) {
  const 今天 = `${数据.时间?.年 ?? 1}-${数据.时间?.月 ?? 3}-${数据.时间?.日 ?? 1}`;
  const 记的 = 数据.今日 ?? {};
  // 日期对不上说明跨天了，按新的一天算
  if (String(记的.日期 ?? '') !== 今天) {
    return { 陪: 一天能陪几次, 出工: 一天能出工几次 };
  }
  return {
    陪: Math.max(0, 一天能陪几次 - Number(记的.陪过 ?? 0)),
    出工: Math.max(0, 一天能出工几次 - Number(记的.出过工 ?? 0)),
  };
}

/** 记一笔今天的消耗。日期变了就先归零再记。 */
export function 记今天的账(数据: any, 项: '陪过' | '喂过' | '药过' | '买过' | '出过工') {
  const 今天 = `${数据.时间?.年 ?? 1}-${数据.时间?.月 ?? 3}-${数据.时间?.日 ?? 1}`;
  if (!数据.今日 || typeof 数据.今日 !== 'object') 数据.今日 = {};
  if (String(数据.今日.日期 ?? '') !== 今天) {
    数据.今日.日期 = 今天;
    数据.今日.陪过 = 0;
    数据.今日.喂过 = 0;
    数据.今日.药过 = 0;
    数据.今日.买过 = 0;
    数据.今日.出过工 = 0;
  }
  数据.今日[项] = Number(数据.今日[项] ?? 0) + 1;
}

function 取阶段(年龄: number) {
  if (年龄 < 7) return 1;
  if (年龄 < 9) return 2;
  if (年龄 < 12) return 3;
  return 4;
}
